    [Test]
    [Arguments("{|KHI002:IntPtr|} handle")]
    [Arguments("out {|KHI002:nint|} handle")]
    [Arguments("ref {|KHI002:nint|} handle")]
    [Arguments("{|KHI002:nint*|} handles")]
    [Arguments("{|KHI002:nint**|} handles")]
    [Arguments("{|KHI002:delegate* unmanaged<nint, void>|} cleanup")]
    public async Task NintAnywhereInAParameterShouldReportKHI002(string parameter)
    {
        Markup source = Markup.Parse(InteropSources.SDL($$"""
                [LibraryImport("SDL3", EntryPoint = "SDL_Fake")]
                internal static partial void Fake({{parameter}});
            """));

        AnalyzerResult result = await AnalyzerRunner<InteropNintAnalyzer>.RunAsync(source);

        await result.CompilationErrors.Should().BeEmpty();
        await result.Located.Should().BeEqualTo(source.Expected);
    }

